<h2 class="h4 mb-3">编辑订单</h2><form method="post" class="card p-3"><?=csrf_field()?><div class="row g-3"><div class="col-md-6"><label class="form-label">标题</label><input class="form-control" name="title" value="<?=h($order['title'])?>"></div><div class="col-md-3"><label class="form-label">订单金额</label><input class="form-control" name="amount" value="<?=h($order['amount'])?>"></div><div class="col-md-3"><label class="form-label">实付金额</label><input class="form-control" name="pay_amount" value="<?=h($order['pay_amount'])?>"></div><div class="col-md-4"><label class="form-label">状态</label><select class="form-select" name="status"><?php foreach ($statuses as $k => $v): ?><option value="<?=h($k)?>" <?=$order['status'] == $k ? 'selected' : ''?>><?=h($v)?></option><?php endforeach; ?></select></div><div class="col-12"><label class="form-label">管理员备注</label><textarea class="form-control" name="admin_remark" rows="3"><?=h($order['admin_remark'])?></textarea></div></div><button class="btn btn-primary mt-3">保存</button></form>
